def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = 4
    sep_rows = [r for r in range(h) if all(v == sep for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    def segments(size, separators):
        out, start = [], 0
        for x in separators:
            if start < x:
                out.append((start, x))
            start = x + 1
        if start < size:
            out.append((start, size))
        return out

    rows = segments(h, sep_rows)
    cols = segments(w, sep_cols)

    bg = max((v for row in grid for v in row if v != sep),
             key=lambda v: sum(row.count(v) for row in grid))
    panels = []
    for r0, r1 in rows:
        for c0, c1 in cols:
            panel = [row[c0:c1] for row in grid[r0:r1]]
            count = sum(v != bg for row in panel for v in row)
            if count:
                panels.append((count, panel))

    if not panels:
        return grid
    template = max(panels, key=lambda x: x[0])[1]
    out = [row[:] for row in grid]
    for r0, r1 in rows:
        for c0, c1 in cols:
            if (r1 - r0, c1 - c0) == (len(template), len(template[0])):
                for i in range(r1 - r0):
                    for j in range(c1 - c0):
                        out[r0 + i][c0 + j] = template[i][j]
    return out
